code2='''def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(row):
        out = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color = row[c]
            start = c
            while c < w and row[c] == color:
                c += 1
            out.append((start, c, color))
        return out

    top_runs, bot_runs = runs(grid[0]), runs(grid[-1])
    pairs = [(a, b) for a in top_runs for b in bot_runs
             if a[2] == b[2] and a[1]-a[0] == b[1]-b[0]]
    if not pairs:
        return g
    topseg, botseg = pairs[0]
    markers = [(r, c, grid[r][c]) for r in range(1, h-1) for c in range(w) if grid[r][c] != bg]
    for r, c, color in markers:
        if topseg[0] <= c < topseg[1]:
            dest = botseg[0] + (c - topseg[0])
            toward_top = True
        elif botseg[0] <= c < botseg[1]:
            dest = topseg[0] + (c - botseg[0])
            toward_top = False
        else:
            continue
        for rr in range(1, h-1):
            g[rr][dest] = color
        # Colors 0 and 6 also draw a ray from their source bar to the marker.
        if color in (0, 6):
            if toward_top:
                for rr in range(1, r):
                    g[rr][c] = color
            else:
                for rr in range(r+1, h-1):
                    g[rr][c] = color
        g[r][c] = 4
    return g
'''
